#!/usr/bin/env python3
# **Do not edit this file.** The node process is provided; each student implements
# the plugin they claimed under platform/plugins/.
"""Node process: gRPC, faults, plugin loader, and a few boot defaults.

Policies (partitioning, replication, leader election, …) live in platform/plugins/. Until a
plugin method is implemented, the node still boots: keys on the first peer, a
local Write, that peer as leader, and ``not owner`` if you talk to the wrong process.
"""
from __future__ import annotations

import argparse
import importlib
import json
import sys
import threading
import time
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path
from typing import Any, Dict, List, Optional, Sequence, Tuple

import grpc

HERE = Path(__file__).resolve().parent.parent
if str(HERE) not in sys.path:
    sys.path.insert(0, str(HERE))

from platform import node_pb2, node_pb2_grpc  # noqa: E402
from platform.plugins import PLUGIN_MODULES  # noqa: E402
from platform.util import MAX_HOP, RpcFailed, hop_count, mode  # noqa: E402

MISSING = object()


class Node(node_pb2_grpc.NodeServicer):
    def __init__(
        self,
        node_id: str,
        host: str,
        port: int,
        peers: Dict[str, Tuple[str, int]],
        n_slots: int = 32,
    ):
        self.node_id = node_id
        self.host = host
        self.port = port
        self.peers = dict(peers)
        self.nodes: List[str] = sorted(self.peers, key=lambda x: (len(x), x))
        if node_id not in self.nodes:
            self.nodes.append(node_id)
            self.nodes.sort(key=lambda x: (len(x), x))
        self.n_slots = n_slots
        self.lock = threading.Lock()
        self.store: Dict[bytes, bytes] = {}
        self.log: List[Tuple[int, bytes, bytes]] = []
        self.last_applied = -1
        self.leader = self.nodes[0] if self.nodes else node_id
        self.term = 0
        self.directory: Dict[bytes, str] = {}
        self.pause = False
        self.delay_ms = 0
        self.drop_to: set[str] = set()
        self.sessions_write: Dict[str, Dict[bytes, bytes]] = {}
        self.sessions_read: Dict[str, Dict[bytes, bytes]] = {}
        self.runs: Dict[str, Dict[str, Any]] = {}
        self.prepared: Dict[str, Tuple[bytes, Optional[bytes], bytes]] = {}
        self.idempotent: set[str] = set()
        self.last_partitioning = ""
        self.plugins = {name: self._load_plugin(name) for name in PLUGIN_MODULES}

    def _load_plugin(self, name: str) -> Any:
        mod = importlib.import_module(f"platform.plugins.{name}")
        return getattr(mod, "Plugin")()

    def _try(self, plugin_name: str, method: str, *args: Any, **kwargs: Any) -> Any:
        plugin = self.plugins.get(plugin_name)
        fn = getattr(plugin, method, None) if plugin is not None else None
        if fn is None:
            return MISSING
        try:
            return fn(*args, **kwargs)
        except NotImplementedError:
            return MISSING

    def other_nodes(self) -> List[str]:
        return [n for n in self.nodes if n != self.node_id]

    def reachable(self) -> List[str]:
        return [n for n in self.nodes if n == self.node_id or n not in self.drop_to]

    def rpc(self, peer: str, method: str, request: Any, timeout_s: float = 1.5) -> Any:
        if peer == self.node_id:
            fn = getattr(self, method)
            return fn(request, None)
        with self.lock:
            drop = peer in self.drop_to
            delay_ms = self.delay_ms
            addr = self.peers.get(peer)
        if drop:
            raise RpcFailed("dropped")
        if delay_ms:
            time.sleep(delay_ms / 1000.0)
        if not addr:
            raise RpcFailed(f"unknown peer {peer}")
        channel = grpc.insecure_channel(f"{addr[0]}:{addr[1]}")
        try:
            stub = node_pb2_grpc.NodeStub(channel)
            fn = getattr(stub, method)
            return fn(request, timeout=timeout_s)
        except Exception as exc:
            raise RpcFailed(str(exc)) from exc
        finally:
            channel.close()

    def _wait(self) -> None:
        deadline = time.time() + 25
        while self.pause and time.time() < deadline:
            time.sleep(0.05)

    def _owner(self, key: bytes, partitioning_mode: str) -> str:
        got = self._try("partitioning", "owner", self, key, partitioning_mode)
        if got is not MISSING and got:
            return str(got)
        return self.nodes[0] if self.nodes else self.node_id

    def status_now(self) -> node_pb2.StatusResponse:
        with self.lock:
            keys = list(self.store)
            peers = list(self.nodes)
            leader = self.leader
            term = self.term
            pause = self.pause
            delay_ms = self.delay_ms
            drop_to = sorted(self.drop_to)
            key_count = len(self.store)
        owners: Dict[str, str] = {}
        per: Dict[str, int] = {n: 0 for n in peers}
        for k in keys:
            o = self._owner(k, self.last_partitioning)
            owners[k.hex()] = o
            per[o] = per.get(o, 0) + 1
        return node_pb2.StatusResponse(
            ok=True,
            node_id=self.node_id,
            leader=leader,
            term=term,
            peers=peers,
            faults=node_pb2.FaultState(pause=pause, delay_ms=delay_ms, drop_to=drop_to),
            key_count=key_count,
            owners=owners,
            keys_per_node=per,
        )

    def _local_write(self, key: bytes, value: bytes) -> None:
        with self.lock:
            index = len(self.log)
            self.log.append((index, key, value))
            self.store[key] = value
            self.last_applied = index

    def Health(self, request, context):
        return node_pb2.HealthResponse(ok=True, node_id=self.node_id)

    def Status(self, request, context):
        self._wait()
        return self.status_now()

    def Fault(self, request, context):
        with self.lock:
            if request.set_pause:
                self.pause = bool(request.pause)
            if request.set_delay:
                self.delay_ms = max(0, int(request.delay_ms))
            if request.set_drop_to:
                self.drop_to = set(request.drop_to)
            if request.set_isolate:
                if request.isolate:
                    self.drop_to = set(self.nodes) - {self.node_id}
                else:
                    self.drop_to = set()
        return self.status_now()

    def Replicate(self, request, context):
        self._wait()
        got = self._try("replication", "on_replicate", self, request)
        if got is not MISSING:
            return got
        merged = self._try("conflicts", "on_replicate", self, request)
        if merged is not MISSING:
            return merged
        with self.lock:
            if request.key:
                self.store[request.key] = request.value
                idx = int(request.index)
                if idx >= 0 and (not self.log or self.log[-1][0] < idx):
                    self.log.append((idx, request.key, request.value))
                self.last_applied = max(self.last_applied, idx)
            return node_pb2.ReplicateResponse(ok=True, applied_index=self.last_applied)

    def Write(self, request, context):
        self._wait()
        if hop_count(request) > MAX_HOP:
            return node_pb2.WriteResponse(ok=False, error="hop limit", owner=self.node_id)
        if request.idempotency_key:
            with self.lock:
                if request.idempotency_key in self.idempotent:
                    return node_pb2.WriteResponse(ok=True, owner=self.node_id, acked_by=[self.node_id])
        partitioning_mode = mode(request.modes, "partitioning")
        if partitioning_mode:
            self.last_partitioning = partitioning_mode
        owner = self._owner(request.key, partitioning_mode)

        admitted = self._try("leader_replication", "admit", self, request, owner)
        if admitted is not MISSING:
            if admitted is not None:
                return admitted
        elif owner != self.node_id:
            routed = self._try("request_routing", "on_write", self, request, owner)
            if routed is not MISSING and routed is not None:
                return routed
            return node_pb2.WriteResponse(ok=False, error="not owner", owner=owner)

        value = request.value
        merged = self._try("conflicts", "on_write", self, request.key, value, mode(request.modes, "conflicts"))
        if merged is not MISSING and merged is not None:
            value = merged

        spread = self._try("write_completion", "spread", self, request.key, value, owner, request.modes)
        if spread is not MISSING:
            resp = spread
        else:
            self._local_write(request.key, value)
            resp = node_pb2.WriteResponse(ok=True, owner=owner, acked_by=[self.node_id])

        if resp.ok:
            self._try("session_models", "on_write", self, request, value)
            self._try("leader_replication", "after_local_write", self, request, value, owner)
            if request.idempotency_key:
                with self.lock:
                    self.idempotent.add(request.idempotency_key)
        self._try("replication", "catch_up", self, request.modes)
        return resp

    def Read(self, request, context):
        self._wait()
        if hop_count(request) > MAX_HOP:
            return node_pb2.ReadResponse(ok=False, error="hop limit", served_by=self.node_id)
        owner = self._owner(request.key, mode(request.modes, "partitioning"))
        sess = self._try("session_models", "on_read", self, request, owner)
        if sess is not MISSING and sess is not None:
            return sess
        repaired = self._try("write_completion", "on_read", self, request, owner)
        if repaired is not MISSING and repaired is not None:
            return repaired
        routed = self._try("request_routing", "on_read", self, request, owner)
        if routed is not MISSING:
            if routed is not None:
                return routed
        elif owner != self.node_id:
            with self.lock:
                local = self.store.get(request.key)
            if local is None:
                return node_pb2.ReadResponse(ok=False, error="not owner", served_by=self.node_id)
        with self.lock:
            found = request.key in self.store
            value = self.store.get(request.key, b"")
            if request.session_id and found:
                self.sessions_read.setdefault(request.session_id, {})[request.key] = value
        return node_pb2.ReadResponse(ok=True, value=value, found=found, served_by=self.node_id)

    def AddNode(self, request, context):
        self._wait()
        got = self._try("partitioning", "on_add_node", self, request)
        if got is not MISSING:
            return got
        if request.pin_key:
            st = self.status_now()
            st.ok = False
            return st
        with self.lock:
            if request.node_id and request.node_id not in self.nodes:
                self.nodes.append(request.node_id)
                self.nodes.sort(key=lambda x: (len(x), x))
            if request.node_id and request.host:
                self.peers[request.node_id] = (request.host, int(request.port or 0))
        return self.status_now()

    def Rebalance(self, request, context):
        self._wait()
        self._try("partitioning", "rebalance", self, request.modes)
        self._try("write_completion", "repair", self, request.modes)
        self._try("conflicts", "heal", self, request.modes)
        self._try("replication", "catch_up", self, request.modes)
        return self.status_now()

    def Elect(self, request, context):
        self._wait()
        got = self._try("leader_election", "on_elect", self, request)
        if got is not MISSING:
            return got
        return node_pb2.ElectResponse(
            ok=True, granted=True, leader=self.leader, term=self.term
        )

    def Prepare(self, request, context):
        self._wait()
        got = self._try("atomic_commit", "on_prepare", self, request)
        if got is not MISSING:
            return got
        with self.lock:
            old = self.store.get(request.key)
            self.prepared[request.txn_id] = (request.key, old, request.value)
        return node_pb2.PrepareResponse(ok=True)

    def Commit(self, request, context):
        self._wait()
        got = self._try("atomic_commit", "on_commit", self, request)
        if got is not MISSING:
            return got
        with self.lock:
            item = self.prepared.pop(request.txn_id, None)
            if item is None:
                return node_pb2.AckResponse(ok=False, error="unknown txn")
            key, _old, value = item
            self.store[key] = value
            self.log.append((len(self.log), key, value))
        return node_pb2.AckResponse(ok=True)

    def Abort(self, request, context):
        self._wait()
        got = self._try("atomic_commit", "on_abort", self, request)
        if got is not MISSING:
            return got
        with self.lock:
            self.prepared.pop(request.txn_id, None)
        return node_pb2.AckResponse(ok=True)

    def Txn(self, request, context):
        self._wait()
        got = self._try("atomic_commit", "run", self, request)
        if got is not MISSING:
            return got
        return node_pb2.TxnResponse(
            ok=False, error="two-key refused", txn_id=request.txn_id, state="refused"
        )

    def RunStart(self, request, context):
        self._wait()
        got = self._try("processing_guarantees", "start", self, request)
        if got is not MISSING:
            return got
        return node_pb2.RunResponse(ok=False, error="not implemented", run_id=request.run_id)

    def RunGet(self, request, context):
        got = self._try("processing_guarantees", "get", self, request)
        if got is not MISSING:
            return got
        run = self.runs.get(request.run_id)
        if not run:
            return node_pb2.RunResponse(ok=False, error="unknown run", run_id=request.run_id)
        return node_pb2.RunResponse(
            ok=True,
            run_id=run["run_id"],
            state=run["state"],
            next_step=run["next_step"],
            applied=list(run["applied"]),
        )

    def RunResume(self, request, context):
        self._wait()
        got = self._try("processing_guarantees", "resume", self, request)
        if got is not MISSING:
            return got
        return node_pb2.RunResponse(ok=False, error="not implemented", run_id=request.run_id)


def parse_peers(text: str) -> Dict[str, Tuple[str, int]]:
    peers: Dict[str, Tuple[str, int]] = {}
    if not text.strip():
        return peers
    for part in text.split(","):
        part = part.strip()
        if not part:
            continue
        nid, addr = part.split("=", 1)
        host, port_s = addr.rsplit(":", 1)
        peers[nid.strip()] = (host.strip(), int(port_s))
    return peers


def load_cluster(path: Path) -> Dict[str, Any]:
    if path.is_file():
        return json.loads(path.read_text())
    return {}


def serve(argv: Optional[Sequence[str]] = None) -> None:
    ap = argparse.ArgumentParser(description="CSC36000 week06 node")
    ap.add_argument("--node-id", required=True)
    ap.add_argument("--host", default="127.0.0.1")
    ap.add_argument("--port", type=int, default=9600)
    ap.add_argument("--peers", default="", help="n0=127.0.0.1:9600,n1=127.0.0.1:9601")
    ap.add_argument("--config", default="cluster.json")
    args = ap.parse_args(argv)

    config_path = Path(args.config)
    if not config_path.is_file():
        alt = HERE / "cluster.json"
        if alt.is_file():
            config_path = alt
    config = load_cluster(config_path)
    peers = parse_peers(args.peers)
    if not peers and config.get("nodes"):
        for n in config["nodes"]:
            peers[str(n["id"])] = (str(n.get("host", args.host)), int(n["port"]))
    peers[args.node_id] = (args.host, int(args.port))
    node = Node(
        args.node_id,
        args.host,
        int(args.port),
        peers,
        n_slots=int(config.get("n_slots", 32)),
    )
    server = grpc.server(ThreadPoolExecutor(max_workers=16))
    node_pb2_grpc.add_NodeServicer_to_server(node, server)
    server.add_insecure_port(f"{args.host}:{int(args.port)}")
    print(
        f"[{args.node_id}] listening on {args.host}:{args.port} peers={sorted(peers)}",
        flush=True,
    )
    server.start()
    try:
        server.wait_for_termination()
    except KeyboardInterrupt:
        server.stop(0)


if __name__ == "__main__":
    serve()
